section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/go-project-structure.json",
  "type": "object",
  "required": [
    "module_path",
    "binaries",
    "internal_packages",
    "vertical_slices"
  ],
  "properties": {
    "module_path": {
      "type": "string",
      "pattern": "^[a-z0-9./_-]+$"
    },
    "binaries": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1
    },
    "internal_packages": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 3
    },
    "vertical_slices": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1
    },
    "top_level_loose_files": {
      "type": "integer",
      "minimum": 0,
      "maximum": 0,
      "description": "Files at the module root outside the allowed set (rule no-top-level-loose-files)."
    },
    "cycles_detected": {
      "type": "integer",
      "minimum": 0,
      "maximum": 0,
      "description": "Import cycles reported by go list -deps (rule no-cyclic-dependencies)."
    },
    "makefile_targets": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Must include build, test, lint (rule makefile-orchestrates)."
    },
    "validated_at": {
      "type": "string",
      "format": "date-time"
    }
  }
}
